        SET @NumeroGanadorId = NEWID();
        VALUES (@NumeroGanadorId, @LoteriaId, @FechaJuego, @Numero);

        PRINT 'Resultado registrado correctamente.';
        RETURN 0;
    END TRY
    BEGIN CATCH
        THROW;
    END CATCH
END
